public class Mannschaft
{
   private String name; 
   private Spieler[] spielerliste;

   public Mannschaft() {
      this.name = "Testmannschaft"; 

      this.spielerliste = new Spieler[4];

      spielerliste[0] = new Spieler("Yusuf", 4, 45);
      spielerliste[1] = new Spieler("Marie", 6, 90);
      spielerliste[2] = new Spieler("Luca", 0, 90);
      spielerliste[3] = new Spieler("Tom", 0, 45);
   }

   public Spieler[] gibSpielerListe() {
      return spielerliste; 
   }

   public int gibToreGesamt() {
      int toreGesamt = 0; 
      for (int i = 0; i < spielerliste.length; i++) {
         toreGesamt += spielerliste[i].gibTore();
      }
      return toreGesamt;
   }
}

